publicabstractclass ValidationProblemQuickFix {
    publicabstractString getName();
    publicabstract void performFix();
    publicString getDescription() { returnnull; }
    publicString getIconPath()    { returnnull; }
  }

public void filterValidationProblems(ValidationProblems validationProblems) {
    for (DocumentPositionedInfo problem : validationProblems.getProblemsList()) {
      validationProblems.addQuickFix(problem, new ValidationProblemQuickFix() {
        publicString getName() {
          return"AI Positron Fix";
        }
        public void performFix() {
          // Change the document here.
        }
        publicString getIconPath() {
          return iconURL.toExternalForm();
        }
      });
    }
  }
